  // The tentative sign of the FMA shall be the sign of the product
  assign tentative_sign = operand_a.sign ^ operand_b.sign;

  // ----------------------
  // Special case handling
  // ----------------------
  fp_t                special_result;
  fpnew_pkg::status_t special_status;
  logic               result_is_special;

  always_comb begin : special_cases
    // Default assignments
    special_result    = '{sign: 1'b0, exponent: '1, mantissa: 2**(MAN_BITS-1)}; // canonical qNaN
    special_status    = '0;
    result_is_special = 1'b0;

    // Handle potentially mixed nan & infinity input => important for the case where infinity and
    // zero are multiplied and added to a qnan.
    // RISC-V mandates raising the NV exception in these cases:
    // (inf * 0) + c or (0 * inf) + c INVALID, no matter c (even quiet NaNs)
    if ((info_a.is_inf && info_b.is_zero) || (info_a.is_zero && info_b.is_inf)) begin
      result_is_special = 1'b1; // bypass FMA, output is the canonical qNaN
      special_status.NV = 1'b1; // invalid operation
    // NaN Inputs cause canonical quiet NaN at the output and maybe invalid OP
    end else if (any_operand_nan) begin
      result_is_special = 1'b1;           // bypass FMA, output is the canonical qNaN
      special_status.NV = signalling_nan; // raise the invalid operation flag if signalling
    // Special cases involving infinity
    end else if (any_operand_inf) begin
      result_is_special = 1'b1; // bypass FMA
      // Effective addition of opposite infinities (??inf - ??inf) is invalid!
      if ((info_a.is_inf || info_b.is_inf) && info_c.is_inf && effective_subtraction)
        special_status.NV = 1'b1; // invalid operation
      // Handle cases where output will be inf because of inf product input
      else if (info_a.is_inf || info_b.is_inf) begin
        // Result is infinity with the sign of the product
        special_result    = '{sign: operand_a.sign ^ operand_b.sign, exponent: '1, mantissa: '0};
      // Handle cases where the addend is inf
      end else if (info_c.is_inf) begin
        // Result is inifinity with sign of the addend (= operand_c)
        special_result    = '{sign: operand_c.sign, exponent: '1, mantissa: '0};
      end
    end
  end

  // ---------------------------
  // Initial exponent data path
  // ---------------------------
  logic signed [EXP_WIDTH-1:0] exponent_a, exponent_b, exponent_c;
  logic signed [EXP_WIDTH-1:0] exponent_addend, exponent_product, exponent_difference;
  logic signed [EXP_WIDTH-1:0] tentative_exponent;

  // Zero-extend exponents into signed container - implicit width extension
  assign exponent_a = signed'({1'b0, operand_a.exponent});
  assign exponent_b = signed'({1'b0, operand_b.exponent});
  assign exponent_c = signed'({1'b0, operand_c.exponent});

  // Calculate internal exponents from encoded values. Real exponents are (ex = Ex - bias + 1 - nx)
  // with Ex the encoded exponent and nx the implicit bit. Internal exponents stay biased.
  assign exponent_addend = signed'(exponent_c + $signed({1'b0, ~info_c.is_normal})); // 0 as subnorm
  // Biased product exponent is the sum of encoded exponents minus the bias.
  assign exponent_product = (info_a.is_zero || info_b.is_zero)
                            ? 2 - signed'(BIAS) // in case the product is zero, set minimum exp.
                            : signed'(exponent_a + info_a.is_subnormal
                                      + exponent_b + info_b.is_subnormal
                                      - signed'(BIAS));
  // Exponent difference is the addend exponent minus the product exponent
  assign exponent_difference = exponent_addend - exponent_product;
  // The tentative exponent will be the larger of the product or addend exponent
  assign tentative_exponent = (exponent_difference > 0) ? exponent_addend : exponent_product;

  // Shift amount for addend based on exponents (unsigned as only right shifts)
  logic [SHIFT_AMOUNT_WIDTH-1:0] addend_shamt;

  always_comb begin : addend_shift_amount
    // Product-anchored case, saturated shift (addend is only in the sticky bit)
    if (exponent_difference <= signed'(-2 * PRECISION_BITS - 1))
      addend_shamt = 3 * PRECISION_BITS + 4;
    // Addend and product will have mutual bits to add
    else if (exponent_difference <= signed'(PRECISION_BITS + 2))
      addend_shamt = unsigned'(signed'(PRECISION_BITS) + 3 - exponent_difference);
    // Addend-anchored case, saturated shift (product is only in the sticky bit)
    else
      addend_shamt = 0;
  end

  // ------------------
  // Product data path
  // ------------------
  logic [PRECISION_BITS-1:0]   mantissa_a, mantissa_b, mantissa_c;
  logic [2*PRECISION_BITS-1:0] product;             // the p*p product is 2p bits wide
  logic [3*PRECISION_BITS+3:0] product_shifted;     // addends are 3p+4 bit wide (including G/R)

  // Add implicit bits to mantissae
  assign mantissa_a = {info_a.is_normal, operand_a.mantissa};
  assign mantissa_b = {info_b.is_normal, operand_b.mantissa};
  assign mantissa_c = {info_c.is_normal, operand_c.mantissa};

  // Mantissa multiplier (a*b)
  assign product = mantissa_a * mantissa_b;

  // Product is placed into a 3p+4 bit wide vector, padded with 2 bits for round and sticky:
  // | 000...000 | product | RS |
  //  <-  p+2  -> <-  2p -> < 2>
  assign product_shifted = product << 2; // constant shift


  // Separate exponent/shift planning from the wide alignment and sticky
  // network. One request still advances per clock in the private always-ready
  // consumer; special values and all response identity move with the payload.
  logic align_valid,align_ready;
  logic ce1_ready;
  logic [3*PRECISION_BITS+3:0] align_product;
  logic [PRECISION_BITS-1:0] align_mantissa_c;
  logic [SHIFT_AMOUNT_WIDTH-1:0] align_shift;
  logic align_sub;
  logic align_sign;
  logic signed [EXP_WIDTH-1:0] align_exp_product;
  logic signed [EXP_WIDTH-1:0] align_exp_diff;
  logic signed [EXP_WIDTH-1:0] align_tent_exp;
  logic align_special;
  fp_t align_special_value;
  fpnew_pkg::status_t align_special_flags;
  fpnew_pkg::roundmode_e align_round;
  assign align_ready=ce1_ready || !align_valid;
  always_ff @(posedge clk_i or negedge rst_ni)begin
    if(!rst_ni)begin
      align_valid<=1'b0;
      align_product<='0;
      align_mantissa_c<='0;
      align_shift<='0;
      align_sub<='0;
      align_sign<='0;
      align_exp_product<='0;
      align_exp_diff<='0;
      align_tent_exp<='0;
      align_special<='0;
      align_special_value<='0;
      align_special_flags<='0;
      align_round<=fpnew_pkg::RNE;
    end else if(flush_i)align_valid<=1'b0;
    else begin
      align_valid<=inp_pipe_valid_q[NUM_INP_REGS];
      if(inp_pipe_valid_q[NUM_INP_REGS])begin
        align_product<=product_shifted;
        align_mantissa_c<=mantissa_c;
        align_shift<=addend_shamt;
        align_sub<=effective_subtraction;
        align_sign<=tentative_sign;
        align_exp_product<=exponent_product;
        align_exp_diff<=exponent_difference;
        align_tent_exp<=tentative_exponent;
        align_special<=result_is_special;
        align_special_value<=special_result;
        align_special_flags<=special_status;
        align_round<=inp_pipe_rnd_mode_q[NUM_INP_REGS];
      end
    end
  end

  // -----------------
  // Addend data path
  // -----------------
  logic [3*PRECISION_BITS+3:0] addend_after_shift;  // upper 3p+4 bits are needed to go on
  logic [PRECISION_BITS-1:0]   addend_sticky_bits;  // up to p bit of shifted addend are sticky
  logic                        sticky_before_add;   // they are compressed into a single sticky bit
  logic [3*PRECISION_BITS+3:0] addend_shifted;      // addends are 3p+4 bit wide (including G/R)
  logic                        inject_carry_in;     // inject carry for subtractions if needed

  // In parallel, the addend is right-shifted according to the exponent difference. Up to p bits
  // are shifted out and compressed into a sticky bit.
  // BEFORE THE SHIFT:
  // | mantissa_c | 000..000 |
  //  <-    p   -> <- 3p+4 ->
  // AFTER THE SHIFT:
  // | 000..........000 | mantissa_c | 000...............0GR |  sticky bits  |
  //  <- addend_shamt -> <-    p   -> <- 2p+4-addend_shamt -> <-  up to p  ->
  assign {addend_after_shift, addend_sticky_bits} =
      (align_mantissa_c << (3 * PRECISION_BITS + 4)) >> align_shift;

  assign sticky_before_add     = (| addend_sticky_bits);
  // assign addend_after_shift[0] = sticky_before_add;

  // In case of a subtraction, the addend is inverted
  assign addend_shifted  = (align_sub) ? ~addend_after_shift : addend_after_shift;
  assign inject_carry_in = align_sub & ~sticky_before_add;


// CE64 elastic checkpoint ce1: arithmetic expressions remain unchanged.
logic ce1_valid;
logic [3*PRECISION_BITS+3:0] ce1_product;
logic [3*PRECISION_BITS+3:0] ce1_addend;
logic [3*PRECISION_BITS+3:0] ce1_positive_addend;
logic ce1_carry;
logic ce1_sub;
logic ce1_sign;
logic signed [EXP_WIDTH-1:0] ce1_exp_product;
logic signed [EXP_WIDTH-1:0] ce1_exp_diff;
logic signed [EXP_WIDTH-1:0] ce1_tent_exp;
logic [SHIFT_AMOUNT_WIDTH-1:0] ce1_shift;
logic ce1_sticky;
logic ce1_special;
fp_t ce1_special_value;
fpnew_pkg::status_t ce1_special_flags;
fpnew_pkg::roundmode_e ce1_round;



assign ce1_ready=mid_pipe_ready[0] || !ce1_valid;
always_ff @(posedge clk_i or negedge rst_ni) begin
if(!rst_ni) begin
ce1_valid<=0;
ce1_product<='0;
ce1_addend<='0;
ce1_positive_addend<='0;
ce1_carry<='0;
ce1_sub<='0;
ce1_sign<='0;
ce1_exp_product<='0;
ce1_exp_diff<='0;
ce1_tent_exp<='0;
ce1_shift<='0;
ce1_sticky<='0;
ce1_special<='0;
ce1_special_value<='0;
ce1_special_flags<='0;
ce1_round<=fpnew_pkg::RNE;



end else if(flush_i) ce1_valid<=0;
else if(ce1_ready) begin
ce1_valid<=align_valid;
if(align_valid) begin
ce1_product<=align_product;
ce1_addend<=addend_shifted;
ce1_positive_addend<=addend_after_shift;
ce1_carry<=inject_carry_in;
ce1_sub<=align_sub;
ce1_sign<=align_sign;
ce1_exp_product<=align_exp_product;
ce1_exp_diff<=align_exp_diff;
ce1_tent_exp<=align_tent_exp;
ce1_shift<=align_shift;
ce1_sticky<=sticky_before_add;
ce1_special<=align_special;
ce1_special_value<=align_special_value;
ce1_special_flags<=align_special_flags;
ce1_round<=align_round;



end end end
  // ------
  // Adder
  // ------
  logic [3*PRECISION_BITS+4:0] sum_pos, sum_neg; // added one bit for the carry
  logic                        sum_carry;        // observe carry bit from positive sum for sign fixing
  logic [3*PRECISION_BITS+3:0] sum;              // discard carry as sum won't overflow
  logic                        final_sign;

  //Mantissa adder (ab+c). In normal addition, it cannot overflow.
  assign sum_pos = ce1_product + ce1_addend + ce1_carry;
  assign sum_carry = sum_pos[3*PRECISION_BITS+4];

  // Parallel adder for negative sum (only used for effective subtractions).
  // Note: ce1_carry is used to complete the negation of the addend in the positive sum but
  // for the negative sum the addend is not negated, so no carry needs to be injected.
  assign sum_neg = ce1_positive_addend - ce1_product;

  // Complement negative sum (can only happen in subtraction -> overflows for positive results)
  assign sum        = (ce1_sub && ~sum_carry) ? sum_neg : sum_pos;

  // In case of a mispredicted subtraction result, do a sign flip
  assign final_sign = (ce1_sub && (sum_carry == ce1_sign))
                      ? 1'b1
                      : (ce1_sub ? 1'b0 : ce1_sign);

  // ---------------
  // Internal pipeline
  // ---------------
  // Pipeline output signals as non-arrays
  logic                          effective_subtraction_q;
  logic signed [EXP_WIDTH-1:0]   exponent_product_q;
  logic signed [EXP_WIDTH-1:0]   exponent_difference_q;
  logic signed [EXP_WIDTH-1:0]   tentative_exponent_q;
  logic [SHIFT_AMOUNT_WIDTH-1:0] addend_shamt_q;
  logic                          sticky_before_add_q;
  logic [3*PRECISION_BITS+3:0]   sum_q;
  logic                          final_sign_q;
  fpnew_pkg::roundmode_e         rnd_mode_q;
  logic                          result_is_special_q;
  fp_t                           special_result_q;
  fpnew_pkg::status_t            special_status_q;
  // Internal pipeline signals, index i holds signal after i register stages
  logic                  [0:NUM_SUM_REGS]                         mid_pipe_eff_sub_q;
  logic signed           [0:NUM_MID_REGS][EXP_WIDTH-1:0]          mid_pipe_exp_prod_q;
  logic signed           [0:NUM_MID_REGS][EXP_WIDTH-1:0]          mid_pipe_exp_diff_q;
  logic signed           [0:NUM_MID_REGS][EXP_WIDTH-1:0]          mid_pipe_tent_exp_q;
  logic                  [0:NUM_MID_REGS][SHIFT_AMOUNT_WIDTH-1:0] mid_pipe_add_shamt_q;
  logic                  [0:NUM_SUM_REGS]                         mid_pipe_sticky_q;
  logic                  [0:NUM_MID_REGS][3*PRECISION_BITS+3:0]   mid_pipe_sum_q;
  logic                  [0:NUM_SUM_REGS]                         mid_pipe_final_sign_q;
  fpnew_pkg::roundmode_e [0:NUM_SUM_REGS]                         mid_pipe_rnd_mode_q;
  logic                  [0:NUM_SUM_REGS]                         mid_pipe_res_is_spec_q;
  fp_t                   [0:NUM_SUM_REGS]                         mid_pipe_spec_res_q;
  fpnew_pkg::status_t    [0:NUM_SUM_REGS]                         mid_pipe_spec_stat_q;



  logic                  [0:NUM_SUM_REGS]                         mid_pipe_valid_q;
  // Ready signal is combinatorial for all stages

  // Input stage: First element of pipeline is taken from upstream logic
  assign mid_pipe_eff_sub_q[0]     = ce1_sub;
  assign mid_pipe_exp_prod_q[0]    = ce1_exp_product;
  assign mid_pipe_exp_diff_q[0]    = ce1_exp_diff;
  assign mid_pipe_tent_exp_q[0]    = ce1_tent_exp;
  assign mid_pipe_add_shamt_q[0]   = ce1_shift;
  assign mid_pipe_sticky_q[0]      = ce1_sticky;
  assign mid_pipe_sum_q[0]         = sum;
  assign mid_pipe_final_sign_q[0]  = final_sign;
  assign mid_pipe_rnd_mode_q[0]    = ce1_round;
  assign mid_pipe_res_is_spec_q[0] = ce1_special;
  assign mid_pipe_spec_res_q[0]    = ce1_special_value;
  assign mid_pipe_spec_stat_q[0]   = ce1_special_flags;



  assign mid_pipe_valid_q[0]       = ce1_valid;
  // Input stage: Propagate pipeline ready signal to input pipe
  assign inp_pipe_ready[NUM_INP_REGS] = align_ready;

  // Generate the register stages
  for (genvar i = 0; i < NUM_SUM_REGS; i++) begin : gen_inside_pipeline
    // Internal register enable for this stage
    logic reg_ena;
    // Determine the ready signal of the current stage - advance the pipeline:
    // 1. if the next stage is ready for our data
    // 2. if the next stage only holds a bubble (not valid) -> we can pop it
    assign mid_pipe_ready[i] = mid_pipe_ready[i+1] | ~mid_pipe_valid_q[i+1];
    // Valid: enabled by ready signal, synchronous clear with the flush signal
    `FFLARNC(mid_pipe_valid_q[i+1], mid_pipe_valid_q[i], mid_pipe_ready[i], flush_i, 1'b0, clk_i, rst_ni)
    // Enable register if pipleine ready and a valid data item is present
    assign reg_ena = (mid_pipe_ready[i] & mid_pipe_valid_q[i]) | reg_ena_i[NUM_INP_REGS + i];
    // Generate the pipeline registers within the stages, use enable-registers
    `FFL(mid_pipe_eff_sub_q[i+1],     mid_pipe_eff_sub_q[i],     reg_ena, '0)
    `FFL(mid_pipe_exp_prod_q[i+1],    mid_pipe_exp_prod_q[i],    reg_ena, '0)
    `FFL(mid_pipe_exp_diff_q[i+1],    mid_pipe_exp_diff_q[i],    reg_ena, '0)
    `FFL(mid_pipe_tent_exp_q[i+1],    mid_pipe_tent_exp_q[i],    reg_ena, '0)
    `FFL(mid_pipe_add_shamt_q[i+1],   mid_pipe_add_shamt_q[i],   reg_ena, '0)
    `FFL(mid_pipe_sticky_q[i+1],      mid_pipe_sticky_q[i],      reg_ena, '0)
    `FFL(mid_pipe_sum_q[i+1],         mid_pipe_sum_q[i],         reg_ena, '0)
    `FFL(mid_pipe_final_sign_q[i+1],  mid_pipe_final_sign_q[i],  reg_ena, '0)
    `FFL(mid_pipe_rnd_mode_q[i+1],    mid_pipe_rnd_mode_q[i],    reg_ena, fpnew_pkg::RNE)
    `FFL(mid_pipe_res_is_spec_q[i+1], mid_pipe_res_is_spec_q[i], reg_ena, '0)
    `FFL(mid_pipe_spec_res_q[i+1],    mid_pipe_spec_res_q[i],    reg_ena, '0)
    `FFL(mid_pipe_spec_stat_q[i+1],   mid_pipe_spec_stat_q[i],   reg_ena, '0)



  end
  // Output stage: assign selected pipe outputs to signals for later use
  assign effective_subtraction_q = mid_pipe_eff_sub_q[NUM_SUM_REGS];
  assign exponent_product_q      = mid_pipe_exp_prod_q[NUM_SUM_REGS];
  assign exponent_difference_q   = mid_pipe_exp_diff_q[NUM_SUM_REGS];
  assign tentative_exponent_q    = mid_pipe_tent_exp_q[NUM_SUM_REGS];
  assign addend_shamt_q          = mid_pipe_add_shamt_q[NUM_SUM_REGS];
  assign sticky_before_add_q     = mid_pipe_sticky_q[NUM_SUM_REGS];
  assign sum_q                   = mid_pipe_sum_q[NUM_SUM_REGS];
  assign final_sign_q            = mid_pipe_final_sign_q[NUM_SUM_REGS];
  assign rnd_mode_q              = mid_pipe_rnd_mode_q[NUM_SUM_REGS];
  assign result_is_special_q     = mid_pipe_res_is_spec_q[NUM_SUM_REGS];
  assign special_result_q        = mid_pipe_spec_res_q[NUM_SUM_REGS];
  assign special_status_q        = mid_pipe_spec_stat_q[NUM_SUM_REGS];

  // --------------
  // Normalization
  // --------------
  logic        [LOWER_SUM_WIDTH-1:0]  sum_lower;              // lower 2p+3 bits of sum are searched
  logic        [LZC_RESULT_WIDTH-1:0] leading_zero_count;     // the number of leading zeroes
  logic signed [LZC_RESULT_WIDTH:0]   leading_zero_count_sgn; // signed leading-zero count
  logic                               lzc_zeroes;             // in case only zeroes found

  logic        [SHIFT_AMOUNT_WIDTH-1:0] norm_shamt; // Normalization shift amount
  logic signed [EXP_WIDTH-1:0]          normalized_exponent;

  logic [3*PRECISION_BITS+4:0] sum_shifted;       // result after first normalization shift
  logic [PRECISION_BITS:0]     final_mantissa;    // final mantissa before rounding with round bit
  logic [2*PRECISION_BITS+2:0] sum_sticky_bits;   // remaining 2p+3 sticky bits after normalization
  logic                        sticky_after_norm; // sticky bit after normalization

  logic signed [EXP_WIDTH-1:0] final_exponent;

  assign sum_lower = sum_q[LOWER_SUM_WIDTH-1:0];

  // Leading zero counter for cancellations
  lzc #(
    .WIDTH ( LOWER_SUM_WIDTH ),
    .MODE  ( 1               ) // MODE = 1 counts leading zeroes
  ) i_lzc (
    .in_i    ( sum_lower          ),
    .cnt_o   ( leading_zero_count ),
    .empty_o ( lzc_zeroes         )
  );

  assign leading_zero_count_sgn = signed'({1'b0, leading_zero_count});

  // Normalization shift amount based on exponents and LZC (unsigned as only left shifts)
  always_comb begin : norm_shift_amount
    // Product-anchored case or cancellations require LZC
    if ((exponent_difference_q <= 0) || (effective_subtraction_q && (exponent_difference_q <= 2))) begin
      // Normal result (biased exponent > 0 and not a zero)
      if ((exponent_product_q - leading_zero_count_sgn + 1 >= 0) && !lzc_zeroes) begin
        // Undo initial product shift, remove the counted zeroes
        norm_shamt          = PRECISION_BITS + 2 + leading_zero_count;
        normalized_exponent = exponent_product_q - leading_zero_count_sgn + 1; // account for shift
      // Subnormal result
      end else begin
        // Cap the shift distance to align mantissa with minimum exponent
        norm_shamt          = unsigned'(signed'(PRECISION_BITS) + 2 + exponent_product_q);
        normalized_exponent = 0; // subnormals encoded as 0
      end
    // Addend-anchored case
    end else begin
      norm_shamt          = addend_shamt_q; // Undo the initial shift
      normalized_exponent = tentative_exponent_q;
    end
  end


// CE64 elastic checkpoint ce2: arithmetic expressions remain unchanged.
logic ce2_valid,ce2_ready;
logic [3*PRECISION_BITS+3:0] ce2_sum;
logic [SHIFT_AMOUNT_WIDTH-1:0] ce2_shift;
logic signed [EXP_WIDTH-1:0] ce2_exponent;
logic ce2_sticky;
logic ce2_sign;
fpnew_pkg::roundmode_e ce2_round;
logic ce2_sub;
logic ce2_special;
fp_t ce2_special_value;
fpnew_pkg::status_t ce2_special_flags;



assign ce2_ready=norm_pipe_ready[0] || !ce2_valid;
always_ff @(posedge clk_i or negedge rst_ni) begin
if(!rst_ni) begin
ce2_valid<=0;
ce2_sum<='0;
ce2_shift<='0;
ce2_exponent<='0;
ce2_sticky<='0;
ce2_sign<='0;
ce2_round<=fpnew_pkg::RNE;
ce2_sub<='0;
ce2_special<='0;
ce2_special_value<='0;
ce2_special_flags<='0;



end else if(flush_i) ce2_valid<=0;
else if(ce2_ready) begin
ce2_valid<=mid_pipe_valid_q[NUM_SUM_REGS];
if(mid_pipe_valid_q[NUM_SUM_REGS]) begin
ce2_sum<=sum_q;
ce2_shift<=norm_shamt;
ce2_exponent<=normalized_exponent;
ce2_sticky<=sticky_before_add_q;
ce2_sign<=final_sign_q;
ce2_round<=rnd_mode_q;
ce2_sub<=effective_subtraction_q;
ce2_special<=result_is_special_q;
ce2_special_value<=special_result_q;
ce2_special_flags<=special_status_q;



end end end
  // Do the large normalization shift
  assign sum_shifted       = ce2_sum << ce2_shift;

  // The addend-anchored case needs a 1-bit normalization since the leading-one can be to the left
  // or right of the (non-carry) MSB of the sum.
  always_comb begin : small_norm
    // Default assignment, discarding carry bit
    {final_mantissa, sum_sticky_bits} = sum_shifted[3*PRECISION_BITS+3:0];
    final_exponent                    = ce2_exponent;

    // The normalized sum has overflown, align right and fix exponent
    if (sum_shifted[3*PRECISION_BITS+4]) begin // check the carry bit
      {final_mantissa, sum_sticky_bits} = sum_shifted[3*PRECISION_BITS+4:1];
      final_exponent                    = ce2_exponent + 1;
    // The normalized sum is normal, nothing to do
    end else if (sum_shifted[3*PRECISION_BITS+3]) begin // check the sum MSB
      // do nothing
    // The normalized sum is still denormal, align left - unless the result is not already subnormal
    end else if (ce2_exponent > 1) begin
      {final_mantissa, sum_sticky_bits} = {sum_shifted[3*PRECISION_BITS+2:0], 1'b0};
      final_exponent                    = ce2_exponent - 1;
    // Otherwise we're denormal
    end else begin
      final_exponent = '0;
    end
  end

  // Update the sticky bit with the shifted-out bits
  assign sticky_after_norm = (| {sum_sticky_bits}) | ce2_sticky;

  // ----------------------------
  // Rounding and classification
  // ----------------------------
  logic                         pre_round_sign;
  logic [EXP_BITS-1:0]          pre_round_exponent;
  logic [MAN_BITS-1:0]          pre_round_mantissa;
  logic [EXP_BITS+MAN_BITS-1:0] pre_round_abs; // absolute value of result before rounding
  logic [1:0]                   round_sticky_bits;

  logic of_before_round, of_after_round; // overflow
  logic uf_after_round; // underflow

  logic                         rounded_sign;
  logic [EXP_BITS+MAN_BITS-1:0] rounded_abs; // absolute value of result after rounding

  // Classification before round. RISC-V mandates checking underflow AFTER rounding!
  assign of_before_round = final_exponent >= 2**(EXP_BITS)-1; // infinity exponent is all ones

  // Assemble result before rounding. In case of overflow, the largest normal value is set.
  assign pre_round_sign     = ce2_sign;
  assign pre_round_exponent = (of_before_round) ? 2**EXP_BITS-2 : unsigned'(final_exponent[EXP_BITS-1:0]);
  assign pre_round_mantissa = (of_before_round) ? '1 : final_mantissa[MAN_BITS:1]; // bit 0 is R bit
  assign pre_round_abs      = {pre_round_exponent, pre_round_mantissa};

  // In case of overflow, the round and sticky bits are set for proper rounding
  assign round_sticky_bits  = (of_before_round) ? 2'b11 : {final_mantissa[0], sticky_after_norm};

  // ----------------------
  // Normalization Pipeline
  // ----------------------
  logic [0:NUM_NORM_REGS][EXP_BITS+MAN_BITS-1:0] norm_pipe_abs_q;
  logic [0:NUM_NORM_REGS]                        norm_pipe_sign_q;
  logic [0:NUM_NORM_REGS][1:0]                   norm_pipe_round_sticky_q;
  fpnew_pkg::roundmode_e [0:NUM_NORM_REGS]       norm_pipe_rnd_mode_q;
  logic [0:NUM_NORM_REGS]                        norm_pipe_eff_sub_q;
  logic [0:NUM_NORM_REGS]                        norm_pipe_of_before_round_q;
  logic [0:NUM_NORM_REGS]                        norm_pipe_sum_sticky_msb_q;
  logic [0:NUM_NORM_REGS]                        norm_pipe_res_is_spec_q;
  fp_t  [0:NUM_NORM_REGS]                        norm_pipe_spec_res_q;
  fpnew_pkg::status_t [0:NUM_NORM_REGS]          norm_pipe_spec_stat_q;



  logic   [0:NUM_NORM_REGS]                      norm_pipe_valid_q;

  assign norm_pipe_abs_q[0]             = pre_round_abs;
  assign norm_pipe_sign_q[0]            = pre_round_sign;
  assign norm_pipe_round_sticky_q[0]    = round_sticky_bits;
  assign norm_pipe_rnd_mode_q[0]        = ce2_round;
  assign norm_pipe_eff_sub_q[0]         = ce2_sub;
  assign norm_pipe_of_before_round_q[0] = of_before_round;
  assign norm_pipe_sum_sticky_msb_q[0]  = sum_sticky_bits[MAN_BITS*2 + 4];
  assign norm_pipe_res_is_spec_q[0]     = ce2_special;
  assign norm_pipe_spec_res_q[0]        = ce2_special_value;
  assign norm_pipe_spec_stat_q[0]       = ce2_special_flags;



  assign norm_pipe_valid_q[0]           = ce2_valid;

  assign mid_pipe_ready[NUM_SUM_REGS] = ce2_ready;

  for (genvar i = 0; i < NUM_NORM_REGS; i++) begin : gen_norm_pipeline
    logic reg_ena;
    assign norm_pipe_ready[i] = norm_pipe_ready[i+1] | ~norm_pipe_valid_q[i+1];
    `FFLARNC(norm_pipe_valid_q[i+1], norm_pipe_valid_q[i], norm_pipe_ready[i], flush_i, 1'b0, clk_i, rst_ni)
    assign reg_ena = (norm_pipe_ready[i] & norm_pipe_valid_q[i]) | reg_ena_i[NUM_INP_REGS + NUM_SUM_REGS + i];
    `FFL(norm_pipe_abs_q[i+1],             norm_pipe_abs_q[i],             reg_ena, '0)
    `FFL(norm_pipe_sign_q[i+1],            norm_pipe_sign_q[i],            reg_ena, '0)
    `FFL(norm_pipe_round_sticky_q[i+1],    norm_pipe_round_sticky_q[i],    reg_ena, '0)
    `FFL(norm_pipe_rnd_mode_q[i+1],        norm_pipe_rnd_mode_q[i],        reg_ena, fpnew_pkg::RNE)
    `FFL(norm_pipe_eff_sub_q[i+1],         norm_pipe_eff_sub_q[i],         reg_ena, '0)
    `FFL(norm_pipe_of_before_round_q[i+1], norm_pipe_of_before_round_q[i], reg_ena, '0)
    `FFL(norm_pipe_sum_sticky_msb_q[i+1],  norm_pipe_sum_sticky_msb_q[i],  reg_ena, '0)
    `FFL(norm_pipe_res_is_spec_q[i+1],     norm_pipe_res_is_spec_q[i],     reg_ena, '0)
    `FFL(norm_pipe_spec_res_q[i+1],        norm_pipe_spec_res_q[i],        reg_ena, '0)
    `FFL(norm_pipe_spec_stat_q[i+1],       norm_pipe_spec_stat_q[i],       reg_ena, '0)



  end

  // Perform the rounding
  // Local inline derivative of frozen fpnew_rounding; see fork-provenance.json.
  if(1)begin : i_fpnew_rounding
    localparam int unsigned AbsWidth=EXP_BITS+MAN_BITS;
    wire [AbsWidth-1:0] abs_value_i=norm_pipe_abs_q[NUM_NORM_REGS];
    wire sign_i=norm_pipe_sign_q[NUM_NORM_REGS];
    wire [1:0] round_sticky_bits_i=norm_pipe_round_sticky_q[NUM_NORM_REGS];
    fpnew_pkg::roundmode_e rnd_mode_i;
    assign rnd_mode_i=norm_pipe_rnd_mode_q[NUM_NORM_REGS];
    wire effective_subtraction_i=norm_pipe_eff_sub_q[NUM_NORM_REGS];
    wire [AbsWidth-1:0] abs_rounded_o;
    wire sign_o;
    logic exact_zero_o;
  logic round_up; // Rounding decision

  // Take the rounding decision according to RISC-V spec
  // RoundMode | Mnemonic | Meaning
  // :--------:|:--------:|:-------
  //    000    |   RNE    | Round to Nearest, ties to Even
  //    001    |   RTZ    | Round towards Zero
  //    010    |   RDN    | Round Down (towards -\infty)
  //    011    |   RUP    | Round Up (towards \infty)
  //    100    |   RMM    | Round to Nearest, ties to Max Magnitude
  //    101    |   ROD    | Round towards odd (this mode is not define in RISC-V FP-SPEC)
  //  others   |          | *invalid*
  always_comb begin : rounding_decision
    unique case (rnd_mode_i)
      fpnew_pkg::RNE: // Decide accoring to round/sticky bits
        unique case (round_sticky_bits_i)
          2'b00,
          2'b01: round_up = 1'b0;           // < ulp/2 away, round down
          2'b10: round_up = abs_value_i[0]; // = ulp/2 away, round towards even result
          2'b11: round_up = 1'b1;           // > ulp/2 away, round up
          default: round_up = fpnew_pkg::DONT_CARE;
        endcase
      fpnew_pkg::RTZ: round_up = 1'b0; // always round down
      fpnew_pkg::RDN: round_up = (| round_sticky_bits_i) ? sign_i  : 1'b0; // to 0 if +, away if -
      fpnew_pkg::RUP: round_up = (| round_sticky_bits_i) ? ~sign_i : 1'b0; // to 0 if -, away if +
      fpnew_pkg::RMM: round_up = round_sticky_bits_i[1]; // round down if < ulp/2 away, else up
      fpnew_pkg::ROD: round_up = ~abs_value_i[0] & (| round_sticky_bits_i);
      default: round_up = fpnew_pkg::DONT_CARE; // propagate x
    endcase
  end

  // Perform the rounding, exponent change and overflow to inf happens automagically
  assign abs_rounded_o = abs_value_i + round_up;

  // True zero result is a zero result without dirty round/sticky bits
  assign exact_zero_o = (abs_value_i == '0) && (round_sticky_bits_i == '0);

  // In case of effective subtraction (thus signs of addition operands must have differed) and a
  // true zero result, the result sign is '-' in case of RDN and '+' for other modes.
  assign sign_o = (exact_zero_o && effective_subtraction_i)
                  ? (rnd_mode_i == fpnew_pkg::RDN)
                  : sign_i;
    assign rounded_abs=abs_rounded_o;
    assign rounded_sign=sign_o;
  end

  // Classification after rounding
  assign uf_after_round = (rounded_abs[EXP_BITS+MAN_BITS-1:MAN_BITS] == '0) // denormal
        || ((norm_pipe_abs_q[NUM_NORM_REGS][EXP_BITS+MAN_BITS-1:MAN_BITS] == '0) && (rounded_abs[EXP_BITS+MAN_BITS-1:MAN_BITS] == 1) &&
           ((norm_pipe_round_sticky_q[NUM_NORM_REGS] != 2'b11) || (!norm_pipe_sum_sticky_msb_q[NUM_NORM_REGS] && ((norm_pipe_rnd_mode_q[NUM_NORM_REGS] == fpnew_pkg::RNE) || (norm_pipe_rnd_mode_q[NUM_NORM_REGS] == fpnew_pkg::RMM)))));
  assign of_after_round = rounded_abs[EXP_BITS+MAN_BITS-1:MAN_BITS] == '1; // exponent all ones

  // -----------------
  // Result selection
  // -----------------
  logic [WIDTH-1:0]     regular_result;
  fpnew_pkg::status_t   regular_status;

  // Assemble regular result
  assign regular_result    = {rounded_sign, rounded_abs};
  assign regular_status.NV = 1'b0; // only valid cases are handled in regular path
  assign regular_status.DZ = 1'b0; // no divisions
  assign regular_status.OF = norm_pipe_of_before_round_q[NUM_NORM_REGS] | of_after_round;   // rounding can introduce overflow
  assign regular_status.UF = uf_after_round & regular_status.NX; // only inexact results raise UF
  assign regular_status.NX = (| norm_pipe_round_sticky_q[NUM_NORM_REGS]) | norm_pipe_of_before_round_q[NUM_NORM_REGS] | of_after_round;

  // Final results for output pipeline
  fp_t                result_d;
  fpnew_pkg::status_t status_d;

  // Select output depending on special case detection
  assign result_d = norm_pipe_res_is_spec_q[NUM_NORM_REGS] ? norm_pipe_spec_res_q[NUM_NORM_REGS] : regular_result;
  assign status_d = norm_pipe_res_is_spec_q[NUM_NORM_REGS] ? norm_pipe_spec_stat_q[NUM_NORM_REGS] : regular_status;

  // ----------------
  // Output Pipeline
  // ----------------
  // Output pipeline signals, index i holds signal after i register stages
  fp_t                [0:NUM_OUT_REGS] out_pipe_result_q;
  fpnew_pkg::status_t [0:NUM_OUT_REGS] out_pipe_status_q;



  logic               [0:NUM_OUT_REGS] out_pipe_valid_q;
  // Ready signal is combinatorial for all stages
  logic [0:NUM_OUT_REGS] out_pipe_ready;

  // Input stage: First element of pipeline is taken from inputs
  assign out_pipe_result_q[0] = result_d;
  assign out_pipe_status_q[0] = status_d;



  assign out_pipe_valid_q[0]  = norm_pipe_valid_q[NUM_NORM_REGS];
  // Input stage: Propagate pipeline ready signal to normalization pipe
  assign norm_pipe_ready[NUM_NORM_REGS] = out_pipe_ready[0];
  // Generate the register stages
  for (genvar i = 0; i < NUM_OUT_REGS; i++) begin : gen_output_pipeline
    // Internal register enable for this stage
    logic reg_ena;
    // Determine the ready signal of the current stage - advance the pipeline:
    // 1. if the next stage is ready for our data
    // 2. if the next stage only holds a bubble (not valid) -> we can pop it
    assign out_pipe_ready[i] = out_pipe_ready[i+1] | ~out_pipe_valid_q[i+1];
    // Valid: enabled by ready signal, synchronous clear with the flush signal
    `FFLARNC(out_pipe_valid_q[i+1], out_pipe_valid_q[i], out_pipe_ready[i], flush_i, 1'b0, clk_i, rst_ni)
    // Enable register if pipleine ready and a valid data item is present
    assign reg_ena = (out_pipe_ready[i] & out_pipe_valid_q[i]) | reg_ena_i[NUM_INP_REGS + NUM_MID_REGS + i];
    // Generate the pipeline registers within the stages, use enable-registers
    `FFL(out_pipe_result_q[i+1], out_pipe_result_q[i], reg_ena, '0)
    `FFL(out_pipe_status_q[i+1], out_pipe_status_q[i], reg_ena, '0)



  end
  // Output stage: Ready travels backwards from output side, driven by downstream circuitry
  assign out_pipe_ready[NUM_OUT_REGS] = out_ready_i;
  // Output stage: assign module outputs
  assign result_o        = out_pipe_result_q[NUM_OUT_REGS];
  assign status_o        = out_pipe_status_q[NUM_OUT_REGS];




  assign out_valid_o     = out_pipe_valid_q[NUM_OUT_REGS];


















endmodule

// Private CE sink-ready consumer; complete public source above is unchanged.
module nx_ce64_fma_ce_sink #(
  parameter fpnew_pkg::fp_format_e   FpFormat    = fpnew_pkg::fp_format_e'(0),
  parameter int unsigned             NumPipeRegs = 0,
  parameter fpnew_pkg::pipe_config_t PipeConfig  = fpnew_pkg::BEFORE,
  parameter type                     TagType     = logic,
  parameter type                     AuxType     = logic,
  // Do not change
  parameter int unsigned WIDTH = fpnew_pkg::fp_width(FpFormat),
  parameter int unsigned ExtRegEnaWidth = NumPipeRegs == 0 ? 1 : NumPipeRegs
) (
  input logic                      clk_i,
  input logic                      rst_ni,
  // Input signals
  input logic [2:0][WIDTH-1:0]     operands_i, // 3 operands
  input logic [2:0]                is_boxed_i, // 3 operands
  input fpnew_pkg::roundmode_e     rnd_mode_i,
  input fpnew_pkg::operation_e     op_i,
  input logic                      op_mod_i,
  input TagType                    tag_i,

  input AuxType                    aux_i,
  // Input Handshake
  input  logic                     in_valid_i,
  output logic                     in_ready_o,
  input  logic                     flush_i,
  // Output signals
  output logic [WIDTH-1:0]         result_o,
  output fpnew_pkg::status_t       status_o,
  output logic                     nonfinite_o,

  output TagType                   tag_o,

  output AuxType                   aux_o,
  // Output handshake
  output logic                     out_valid_o,
  // Indication of valid data in flight

  // External register enable override
  input  logic [ExtRegEnaWidth-1:0] reg_ena_i
  // Early valid for external structural hazard generation

);
  wire out_ready_i=1'b1;

  // ----------
  // Constants
  // ----------
  parameter int unsigned EXP_BITS = fpnew_pkg::exp_bits(FpFormat);
  parameter int unsigned MAN_BITS = fpnew_pkg::man_bits(FpFormat);
  localparam int unsigned BIAS     = fpnew_pkg::bias(FpFormat);
  // Precision bits 'p' include the implicit bit
  localparam int unsigned PRECISION_BITS = MAN_BITS + 1;
  // The lower 2p+3 bits of the internal FMA result will be needed for leading-zero detection
  localparam int unsigned LOWER_SUM_WIDTH  = 2 * PRECISION_BITS + 3;
  localparam int unsigned LZC_RESULT_WIDTH = $clog2(LOWER_SUM_WIDTH);
  // Internal exponent width of FMA must accomodate all meaningful exponent values in order to avoid
  // datapath leakage. This is either given by the exponent bits or the width of the LZC result.
  // In most reasonable FP formats the internal exponent will be wider than the LZC result.
  localparam int unsigned EXP_WIDTH = unsigned'(fpnew_pkg::maximum(EXP_BITS + 2, LZC_RESULT_WIDTH));
  // Shift amount width: maximum internal mantissa size is 3p+4 bits
  localparam int unsigned SHIFT_AMOUNT_WIDTH = $clog2(3 * PRECISION_BITS + 5);
  // Pipelines
  localparam NUM_INP_REGS = PipeConfig == fpnew_pkg::BEFORE
                            ? NumPipeRegs
                            : (PipeConfig == fpnew_pkg::DISTRIBUTED
                               ? ((NumPipeRegs + 1) / 3) // Second to get distributed regs
                               : 0); // no regs here otherwise
  localparam NUM_MID_REGS = PipeConfig == fpnew_pkg::INSIDE
                          ? NumPipeRegs
                          : (PipeConfig == fpnew_pkg::DISTRIBUTED
                             ? ((NumPipeRegs + 2) / 3) // First to get distributed regs
                             : 0); // no regs here otherwise
  localparam NUM_SUM_REGS = (NUM_MID_REGS > 1) ? (NUM_MID_REGS - 1) : NUM_MID_REGS;
  // PIPE_REGS=3 is the production ADD sink. Keep its normalization
  // result in a register before rounded classification/result selection.
  localparam NUM_EXTRA_NORM_REGS = (FpFormat==fpnew_pkg::FP32 &&
      NumPipeRegs==3 && PipeConfig==fpnew_pkg::DISTRIBUTED) ? 1 : 0;
  localparam NUM_NORM_REGS = ((NUM_MID_REGS > 1) ? 1 : 0)+NUM_EXTRA_NORM_REGS;
  localparam NUM_OUT_REGS = PipeConfig == fpnew_pkg::AFTER
                            ? NumPipeRegs
                            : (PipeConfig == fpnew_pkg::DISTRIBUTED
                               ? (NumPipeRegs / 3) // Last to get distributed regs
                               : 0); // no regs here otherwise

  logic [0:NUM_SUM_REGS] mid_pipe_ready;
  logic [0:NUM_NORM_REGS] norm_pipe_ready;

  // ----------------
  // Type definition
  // ----------------
  typedef struct packed {
    logic                sign;
    logic [EXP_BITS-1:0] exponent;
    logic [MAN_BITS-1:0] mantissa;
  } fp_t;

  // ---------------
  // Input pipeline
  // ---------------
  // Input pipeline signals, index i holds signal after i register stages
  logic                  [0:NUM_INP_REGS][2:0][WIDTH-1:0] inp_pipe_operands_q;
  logic                  [0:NUM_INP_REGS][2:0]            inp_pipe_is_boxed_q;
  fpnew_pkg::roundmode_e [0:NUM_INP_REGS]                 inp_pipe_rnd_mode_q;
  fpnew_pkg::operation_e [0:NUM_INP_REGS]                 inp_pipe_op_q;
  logic                  [0:NUM_INP_REGS]                 inp_pipe_op_mod_q;
  TagType                [0:NUM_INP_REGS]                 inp_pipe_tag_q;

  AuxType                [0:NUM_INP_REGS]                 inp_pipe_aux_q;
  logic                  [0:NUM_INP_REGS]                 inp_pipe_valid_q;
  // Ready signal is combinatorial for all stages
  logic [0:NUM_INP_REGS] inp_pipe_ready;

  // Input stage: First element of pipeline is taken from inputs
  assign inp_pipe_operands_q[0] = operands_i;
  assign inp_pipe_is_boxed_q[0] = is_boxed_i;
  assign inp_pipe_rnd_mode_q[0] = rnd_mode_i;
  assign inp_pipe_op_q[0]       = op_i;
  assign inp_pipe_op_mod_q[0]   = op_mod_i;
  assign inp_pipe_tag_q[0]      = tag_i;

  assign inp_pipe_aux_q[0]      = aux_i;
  assign inp_pipe_valid_q[0]    = in_valid_i;
  // Input stage: Propagate pipeline ready signal to updtream circuitry
  assign in_ready_o = inp_pipe_ready[0];
  // Generate the register stages
  for (genvar i = 0; i < NUM_INP_REGS; i++) begin : gen_input_pipeline
    // Internal register enable for this stage
    logic reg_ena;
    // Determine the ready signal of the current stage - advance the pipeline:
    // 1. if the next stage is ready for our data
    // 2. if the next stage only holds a bubble (not valid) -> we can pop it
    assign inp_pipe_ready[i] = inp_pipe_ready[i+1] | ~inp_pipe_valid_q[i+1];
    // Valid: enabled by ready signal, synchronous clear with the flush signal
    `ifndef VERILATOR
    /* synopsys sync_set_reset "flush_i" */
    `endif
    always_ff @(posedge (clk_i) or negedge (rst_ni)) begin
      if (!rst_ni) begin
        inp_pipe_valid_q[i+1] <= (1'b0);
      end else begin
        inp_pipe_valid_q[i+1] <= (flush_i) ? (1'b0) : (inp_pipe_valid_q[i]);
      end
    end
    // Enable register if pipleine ready and a valid data item is present
    assign reg_ena = (inp_pipe_ready[i] & inp_pipe_valid_q[i]) | reg_ena_i[i];
    // Generate the pipeline registers within the stages, use enable-registers
    `FFL(inp_pipe_operands_q[i+1], inp_pipe_operands_q[i], reg_ena, '0)
    `FFL(inp_pipe_is_boxed_q[i+1], inp_pipe_is_boxed_q[i], reg_ena, '0)
    `FFL(inp_pipe_rnd_mode_q[i+1], inp_pipe_rnd_mode_q[i], reg_ena, fpnew_pkg::RNE)
    `FFL(inp_pipe_op_q[i+1],       inp_pipe_op_q[i],       reg_ena, fpnew_pkg::FMADD)
    `FFL(inp_pipe_op_mod_q[i+1],   inp_pipe_op_mod_q[i],   reg_ena, '0)
    `FFL(inp_pipe_tag_q[i+1],      inp_pipe_tag_q[i],      reg_ena, TagType'('0))

    `FFL(inp_pipe_aux_q[i+1],      inp_pipe_aux_q[i],      reg_ena, AuxType'('0))
  end

  // -----------------
  // Input processing
  // -----------------
  // Project-local classifier projections; vendor originals remain unchanged.
  typedef struct packed {
    logic is_normal,is_subnormal,is_zero,is_inf,is_nan,is_signalling;
  } nx_fma_info_ab_t;
  typedef struct packed {
    logic is_normal,is_inf,is_nan,is_signalling;
  } nx_fma_info_c_t;
  function automatic nx_fma_info_ab_t classify_ab(
      input logic [EXP_BITS-1:0] exponent,
      input logic [MAN_BITS-1:0] mantissa,input logic is_boxed);
    logic is_normal,is_zero,is_subnormal,is_inf,is_nan,is_signalling;
    begin
      is_normal = is_boxed && (exponent != '0) && (exponent != '1);
      is_zero = is_boxed && (exponent == '0) && (mantissa == '0);
      is_subnormal = is_boxed && (exponent == '0) && !is_zero;
      is_inf = is_boxed && ((exponent == '1) && (mantissa == '0));
      is_nan = !is_boxed || ((exponent == '1) && (mantissa != '0));
      is_signalling = is_boxed && is_nan && (mantissa[MAN_BITS-1] == 1'b0);
      classify_ab = {is_normal,is_subnormal,is_zero,is_inf,is_nan,is_signalling};
    end
  endfunction
  function automatic nx_fma_info_c_t classify_c(
      input logic [EXP_BITS-1:0] exponent,
      input logic [MAN_BITS-1:0] mantissa,input logic is_boxed);
    logic is_normal,is_inf,is_nan,is_signalling;
    begin
      is_normal = is_boxed && (exponent != '0) && (exponent != '1);
      is_inf = is_boxed && ((exponent == '1) && (mantissa == '0));
      is_nan = !is_boxed || ((exponent == '1) && (mantissa != '0));
      is_signalling = is_boxed && is_nan && (mantissa[MAN_BITS-1] == 1'b0);
      classify_c = {is_normal,is_inf,is_nan,is_signalling};
    end
  endfunction
  fp_t operand_a,operand_b,operand_c;
  nx_fma_info_ab_t info_a,info_b;
  nx_fma_info_c_t info_c;

  // Operation selection and operand adjustment
  // | \c op_q  | \c op_mod_q | Operation Adjustment
  // |:--------:|:-----------:|---------------------
  // | FMADD    | \c 0        | FMADD: none
  // | FMADD    | \c 1        | FMSUB: Invert sign of operand C
  // | FNMSUB   | \c 0        | FNMSUB: Invert sign of operand A
  // | FNMSUB   | \c 1        | FNMADD: Invert sign of operands A and C
  // | ADD      | \c 0        | ADD: Set operand A to +1.0
  // | ADD      | \c 1        | SUB: Set operand A to +1.0, invert sign of operand C
  // | MUL      | \c 0        | MUL: Set operand C to +0.0 or -0.0 depending on the rounding mode
  // | *others* | \c -        | *invalid*
  // \note \c op_mod_q always inverts the sign of the addend.
  always_comb begin : op_select

    // Default assignments - packing-order-agnostic
    operand_a = inp_pipe_operands_q[NUM_INP_REGS][0];
    operand_b = inp_pipe_operands_q[NUM_INP_REGS][1];
    operand_c = {inp_pipe_operands_q[NUM_INP_REGS][2][WIDTH-1]^inp_pipe_op_mod_q[NUM_INP_REGS],inp_pipe_operands_q[NUM_INP_REGS][2][WIDTH-2:0]};
    info_a    = classify_ab(inp_pipe_operands_q[NUM_INP_REGS][0][WIDTH-2:MAN_BITS],inp_pipe_operands_q[NUM_INP_REGS][0][MAN_BITS-1:0],inp_pipe_is_boxed_q[NUM_INP_REGS][0]);
    info_b    = classify_ab(inp_pipe_operands_q[NUM_INP_REGS][1][WIDTH-2:MAN_BITS],inp_pipe_operands_q[NUM_INP_REGS][1][MAN_BITS-1:0],inp_pipe_is_boxed_q[NUM_INP_REGS][1]);
    info_c    = classify_c(inp_pipe_operands_q[NUM_INP_REGS][2][WIDTH-2:MAN_BITS],inp_pipe_operands_q[NUM_INP_REGS][2][MAN_BITS-1:0],inp_pipe_is_boxed_q[NUM_INP_REGS][2]);

    // Default operand C above already includes the original op_mod_q sign XOR.

    unique case (inp_pipe_op_q[NUM_INP_REGS])
      fpnew_pkg::FMADD:  ; // do nothing
      fpnew_pkg::FNMSUB: operand_a.sign = ~operand_a.sign; // invert sign of product
      fpnew_pkg::ADD,
      fpnew_pkg::ADDS: begin // Set multiplicand to +1
        operand_a = '{sign: 1'b0, exponent: BIAS, mantissa: '0};
        info_a    = '{is_normal: 1'b1, default: 1'b0}; //normal, boxed value.
      end
      fpnew_pkg::MUL: begin // Set addend to +0 or -0, depending whether the rounding mode is RDN
        if (inp_pipe_rnd_mode_q[NUM_INP_REGS] == fpnew_pkg::RDN)
          operand_c = '{sign: 1'b0, exponent: '0, mantissa: '0};
        else
          operand_c = '{sign: 1'b1, exponent: '0, mantissa: '0};
        info_c    = '{default: 1'b0}; //zero, boxed value.
      end
      default: begin // propagate don't cares
        operand_a  = '{default: fpnew_pkg::DONT_CARE};
        operand_b  = '{default: fpnew_pkg::DONT_CARE};
        operand_c  = '{default: fpnew_pkg::DONT_CARE};
        info_a     = '{default: fpnew_pkg::DONT_CARE};
        info_b     = '{default: fpnew_pkg::DONT_CARE};
        info_c     = '{default: fpnew_pkg::DONT_CARE};
      end
    endcase
  end

  // ---------------------
  // Input classification
  // ---------------------
  logic any_operand_inf;
  logic any_operand_nan;
  logic signalling_nan;
  logic effective_subtraction;
  logic tentative_sign;

  // Reduction for special case handling
  assign any_operand_inf = (| {info_a.is_inf,        info_b.is_inf,        info_c.is_inf});
  assign any_operand_nan = (| {info_a.is_nan,        info_b.is_nan,        info_c.is_nan});
  assign signalling_nan  = (| {info_a.is_signalling, info_b.is_signalling, info_c.is_signalling});
  // Effective subtraction in FMA occurs when product and addend signs differ
  assign effective_subtraction = operand_a.sign ^ operand_b.sign ^ operand_c.sign;
  // The tentative sign of the FMA shall be the sign of the product
  assign tentative_sign = operand_a.sign ^ operand_b.sign;

  // ----------------------
  // Special case handling
  // ----------------------
  fp_t                special_result;
  fpnew_pkg::status_t special_status;
  logic               result_is_special;

  always_comb begin : special_cases
    // Default assignments
    special_result    = '{sign: 1'b0, exponent: '1, mantissa: 2**(MAN_BITS-1)}; // canonical qNaN
    special_status    = '0;
    result_is_special = 1'b0;

    // Handle potentially mixed nan & infinity input => important for the case where infinity and
    // zero are multiplied and added to a qnan.
    // RISC-V mandates raising the NV exception in these cases:
    // (inf * 0) + c or (0 * inf) + c INVALID, no matter c (even quiet NaNs)
    if ((info_a.is_inf && info_b.is_zero) || (info_a.is_zero && info_b.is_inf)) begin
      result_is_special = 1'b1; // bypass FMA, output is the canonical qNaN
      special_status.NV = 1'b1; // invalid operation
    // NaN Inputs cause canonical quiet NaN at the output and maybe invalid OP
    end else if (any_operand_nan) begin
      result_is_special = 1'b1;           // bypass FMA, output is the canonical qNaN
      special_status.NV = signalling_nan; // raise the invalid operation flag if signalling
    // Special cases involving infinity
    end else if (any_operand_inf) begin
      result_is_special = 1'b1; // bypass FMA
      // Effective addition of opposite infinities (??inf - ??inf) is invalid!
      if ((info_a.is_inf || info_b.is_inf) && info_c.is_inf && effective_subtraction)
        special_status.NV = 1'b1; // invalid operation
      // Handle cases where output will be inf because of inf product input
      else if (info_a.is_inf || info_b.is_inf) begin
        // Result is infinity with the sign of the product
        special_result    = '{sign: operand_a.sign ^ operand_b.sign, exponent: '1, mantissa: '0};
      // Handle cases where the addend is inf
      end else if (info_c.is_inf) begin
        // Result is inifinity with sign of the addend (= operand_c)
        special_result    = '{sign: operand_c.sign, exponent: '1, mantissa: '0};
      end
    end
  end

  // ---------------------------
  // Initial exponent data path
  // ---------------------------
  logic signed [EXP_WIDTH-1:0] exponent_a, exponent_b, exponent_c;
  logic signed [EXP_WIDTH-1:0] exponent_addend, exponent_product, exponent_difference;
  logic signed [EXP_WIDTH-1:0] tentative_exponent;

  // Zero-extend exponents into signed container - implicit width extension
  assign exponent_a = signed'({1'b0, operand_a.exponent});
  assign exponent_b = signed'({1'b0, operand_b.exponent});
  assign exponent_c = signed'({1'b0, operand_c.exponent});

  // Calculate internal exponents from encoded values. Real exponents are (ex = Ex - bias + 1 - nx)
  // with Ex the encoded exponent and nx the implicit bit. Internal exponents stay biased.
  assign exponent_addend = signed'(exponent_c + $signed({1'b0, ~info_c.is_normal})); // 0 as subnorm
  // Biased product exponent is the sum of encoded exponents minus the bias.
  assign exponent_product = (info_a.is_zero || info_b.is_zero)
                            ? 2 - signed'(BIAS) // in case the product is zero, set minimum exp.
                            : signed'(exponent_a + info_a.is_subnormal
                                      + exponent_b + info_b.is_subnormal
                                      - signed'(BIAS));
  // Exponent difference is the addend exponent minus the product exponent
  assign exponent_difference = exponent_addend - exponent_product;
  // The tentative exponent will be the larger of the product or addend exponent
  assign tentative_exponent = (exponent_difference > 0) ? exponent_addend : exponent_product;

  // Shift amount for addend based on exponents (unsigned as only right shifts)
  logic [SHIFT_AMOUNT_WIDTH-1:0] addend_shamt;

  always_comb begin : addend_shift_amount
    // Product-anchored case, saturated shift (addend is only in the sticky bit)
    if (exponent_difference <= signed'(-2 * PRECISION_BITS - 1))
      addend_shamt = 3 * PRECISION_BITS + 4;
    // Addend and product will have mutual bits to add
    else if (exponent_difference <= signed'(PRECISION_BITS + 2))
      addend_shamt = unsigned'(signed'(PRECISION_BITS) + 3 - exponent_difference);
    // Addend-anchored case, saturated shift (product is only in the sticky bit)
    else
      addend_shamt = 0;
  end

  // ------------------
  // Product data path
  // ------------------
  logic [PRECISION_BITS-1:0]   mantissa_a, mantissa_b, mantissa_c;
  logic [2*PRECISION_BITS-1:0] product;             // the p*p product is 2p bits wide
  logic [3*PRECISION_BITS+3:0] product_shifted;     // addends are 3p+4 bit wide (including G/R)

  // Add implicit bits to mantissae
  assign mantissa_a = {info_a.is_normal, operand_a.mantissa};
  assign mantissa_b = {info_b.is_normal, operand_b.mantissa};
  assign mantissa_c = {info_c.is_normal, operand_c.mantissa};

  // Mantissa multiplier (a*b)
  assign product = mantissa_a * mantissa_b;

  // Product is placed into a 3p+4 bit wide vector, padded with 2 bits for round and sticky:
  // | 000...000 | product | RS |
  //  <-  p+2  -> <-  2p -> < 2>
  assign product_shifted = product << 2; // constant shift


  // Separate exponent/shift planning from the wide alignment and sticky
  // network. One request still advances per clock in the private always-ready
  // consumer; special values and all response identity move with the payload.
  logic align_valid,align_ready;
  logic ce1_ready;
  logic [3*PRECISION_BITS+3:0] align_product;
  logic [PRECISION_BITS-1:0] align_mantissa_c;
  logic [SHIFT_AMOUNT_WIDTH-1:0] align_shift;
  logic align_sub;
  logic align_sign;
  logic signed [EXP_WIDTH-1:0] align_exp_product;
  logic signed [EXP_WIDTH-1:0] align_exp_diff;
  logic signed [EXP_WIDTH-1:0] align_tent_exp;
  logic align_special;
  fp_t align_special_value;
  fpnew_pkg::status_t align_special_flags;
  fpnew_pkg::roundmode_e align_round;
  TagType align_tag;
  AuxType align_aux;
  assign align_ready=ce1_ready || !align_valid;
  always_ff @(posedge clk_i or negedge rst_ni)begin
    if(!rst_ni)begin
      align_valid<=1'b0;
      align_product<='0;
      align_mantissa_c<='0;
      align_shift<='0;
      align_sub<='0;
      align_sign<='0;
      align_exp_product<='0;
      align_exp_diff<='0;
      align_tent_exp<='0;
      align_special<='0;
      align_special_value<='0;
      align_special_flags<='0;
      align_round<=fpnew_pkg::RNE;
      align_tag<='0;
      align_aux<='0;
    end else if(flush_i)align_valid<=1'b0;
    else begin
      align_valid<=inp_pipe_valid_q[NUM_INP_REGS];
      if(inp_pipe_valid_q[NUM_INP_REGS])begin
        align_product<=product_shifted;
        align_mantissa_c<=mantissa_c;
        align_shift<=addend_shamt;
        align_sub<=effective_subtraction;
        align_sign<=tentative_sign;
        align_exp_product<=exponent_product;
        align_exp_diff<=exponent_difference;
        align_tent_exp<=tentative_exponent;
        align_special<=result_is_special;
        align_special_value<=special_result;
        align_special_flags<=special_status;
        align_round<=inp_pipe_rnd_mode_q[NUM_INP_REGS];
        align_tag<=inp_pipe_tag_q[NUM_INP_REGS];
        align_aux<=inp_pipe_aux_q[NUM_INP_REGS];
      end
    end
  end

  // -----------------
  // Addend data path
  // -----------------
  logic [3*PRECISION_BITS+3:0] addend_after_shift;  // upper 3p+4 bits are needed to go on
  logic [PRECISION_BITS-1:0]   addend_sticky_bits;  // up to p bit of shifted addend are sticky
  logic                        sticky_before_add;   // they are compressed into a single sticky bit
  logic [3*PRECISION_BITS+3:0] addend_shifted;      // addends are 3p+4 bit wide (including G/R)
  logic                        inject_carry_in;     // inject carry for subtractions if needed

  // In parallel, the addend is right-shifted according to the exponent difference. Up to p bits
  // are shifted out and compressed into a sticky bit.
  // BEFORE THE SHIFT:
  // | mantissa_c | 000..000 |
  //  <-    p   -> <- 3p+4 ->
  // AFTER THE SHIFT:
  // | 000..........000 | mantissa_c | 000...............0GR |  sticky bits  |
  //  <- addend_shamt -> <-    p   -> <- 2p+4-addend_shamt -> <-  up to p  ->
  assign {addend_after_shift, addend_sticky_bits} =
      (align_mantissa_c << (3 * PRECISION_BITS + 4)) >> align_shift;

  assign sticky_before_add     = (| addend_sticky_bits);
  // assign addend_after_shift[0] = sticky_before_add;

  // In case of a subtraction, the addend is inverted
  assign addend_shifted  = (align_sub) ? ~addend_after_shift : addend_after_shift;
  assign inject_carry_in = align_sub & ~sticky_before_add;


// CE64 elastic checkpoint ce1: arithmetic expressions remain unchanged.
logic ce1_valid;
logic [3*PRECISION_BITS+3:0] ce1_product;
logic [3*PRECISION_BITS+3:0] ce1_addend;
logic [3*PRECISION_BITS+3:0] ce1_positive_addend;
logic ce1_carry;
logic ce1_sub;
logic ce1_sign;
logic signed [EXP_WIDTH-1:0] ce1_exp_product;
logic signed [EXP_WIDTH-1:0] ce1_exp_diff;
logic signed [EXP_WIDTH-1:0] ce1_tent_exp;
logic [SHIFT_AMOUNT_WIDTH-1:0] ce1_shift;
logic ce1_sticky;
logic ce1_special;
fp_t ce1_special_value;
fpnew_pkg::status_t ce1_special_flags;
fpnew_pkg::roundmode_e ce1_round;
TagType ce1_tag;

AuxType ce1_aux;
assign ce1_ready=mid_pipe_ready[0] || !ce1_valid;
always_ff @(posedge clk_i or negedge rst_ni) begin
if(!rst_ni) begin
ce1_valid<=0;
ce1_product<='0;
ce1_addend<='0;
ce1_positive_addend<='0;
ce1_carry<='0;
ce1_sub<='0;
ce1_sign<='0;
ce1_exp_product<='0;
ce1_exp_diff<='0;
ce1_tent_exp<='0;
ce1_shift<='0;
ce1_sticky<='0;
ce1_special<='0;
ce1_special_value<='0;
ce1_special_flags<='0;
ce1_round<=fpnew_pkg::RNE;
ce1_tag<=TagType'('0);

ce1_aux<=AuxType'('0);
end else if(flush_i) ce1_valid<=0;
else begin
ce1_valid<=align_valid;
if(align_valid) begin
ce1_product<=align_product;
ce1_addend<=addend_shifted;
ce1_positive_addend<=addend_after_shift;
ce1_carry<=inject_carry_in;
ce1_sub<=align_sub;
ce1_sign<=align_sign;
ce1_exp_product<=align_exp_product;
ce1_exp_diff<=align_exp_diff;
ce1_tent_exp<=align_tent_exp;
ce1_shift<=align_shift;
ce1_sticky<=sticky_before_add;
ce1_special<=align_special;
ce1_special_value<=align_special_value;
ce1_special_flags<=align_special_flags;
ce1_round<=align_round;
ce1_tag<=align_tag;

ce1_aux<=align_aux;
end end end
  // ------
  // Adder
  // ------
  logic [3*PRECISION_BITS+4:0] sum_pos, sum_neg; // added one bit for the carry
  logic                        sum_carry;        // observe carry bit from positive sum for sign fixing
  logic [3*PRECISION_BITS+3:0] sum;              // discard carry as sum won't overflow
  logic                        final_sign;

  //Mantissa adder (ab+c). In normal addition, it cannot overflow.
  assign sum_pos = ce1_product + ce1_addend + ce1_carry;
  assign sum_carry = sum_pos[3*PRECISION_BITS+4];

  // Parallel adder for negative sum (only used for effective subtractions).
  // Note: ce1_carry is used to complete the negation of the addend in the positive sum but
  // for the negative sum the addend is not negated, so no carry needs to be injected.
  assign sum_neg = ce1_positive_addend - ce1_product;

  // Complement negative sum (can only happen in subtraction -> overflows for positive results)
  assign sum        = (ce1_sub && ~sum_carry) ? sum_neg : sum_pos;

  // In case of a mispredicted subtraction result, do a sign flip
  assign final_sign = (ce1_sub && (sum_carry == ce1_sign))
                      ? 1'b1
                      : (ce1_sub ? 1'b0 : ce1_sign);

  // ---------------
  // Internal pipeline
  // ---------------
  // Pipeline output signals as non-arrays
  logic                          effective_subtraction_q;
  logic signed [EXP_WIDTH-1:0]   exponent_product_q;
  logic signed [EXP_WIDTH-1:0]   exponent_difference_q;
  logic signed [EXP_WIDTH-1:0]   tentative_exponent_q;
  logic [SHIFT_AMOUNT_WIDTH-1:0] addend_shamt_q;
  logic                          sticky_before_add_q;
  logic [3*PRECISION_BITS+3:0]   sum_q;
  logic                          final_sign_q;
  fpnew_pkg::roundmode_e         rnd_mode_q;
  logic                          result_is_special_q;
  fp_t                           special_result_q;
  fpnew_pkg::status_t            special_status_q;
  // Internal pipeline signals, index i holds signal after i register stages
  logic                  [0:NUM_SUM_REGS]                         mid_pipe_eff_sub_q;
  logic signed           [0:NUM_MID_REGS][EXP_WIDTH-1:0]          mid_pipe_exp_prod_q;
  logic signed           [0:NUM_MID_REGS][EXP_WIDTH-1:0]          mid_pipe_exp_diff_q;
  logic signed           [0:NUM_MID_REGS][EXP_WIDTH-1:0]          mid_pipe_tent_exp_q;
  logic                  [0:NUM_MID_REGS][SHIFT_AMOUNT_WIDTH-1:0] mid_pipe_add_shamt_q;
  logic                  [0:NUM_SUM_REGS]                         mid_pipe_sticky_q;
  logic                  [0:NUM_MID_REGS][3*PRECISION_BITS+3:0]   mid_pipe_sum_q;
  logic                  [0:NUM_SUM_REGS]                         mid_pipe_final_sign_q;
  fpnew_pkg::roundmode_e [0:NUM_SUM_REGS]                         mid_pipe_rnd_mode_q;
  logic                  [0:NUM_SUM_REGS]                         mid_pipe_res_is_spec_q;
  fp_t                   [0:NUM_SUM_REGS]                         mid_pipe_spec_res_q;
  fpnew_pkg::status_t    [0:NUM_SUM_REGS]                         mid_pipe_spec_stat_q;
  TagType                [0:NUM_SUM_REGS]                         mid_pipe_tag_q;

  AuxType                [0:NUM_SUM_REGS]                         mid_pipe_aux_q;
  logic                  [0:NUM_SUM_REGS]                         mid_pipe_valid_q;
  // Ready signal is combinatorial for all stages

  // Input stage: First element of pipeline is taken from upstream logic
  assign mid_pipe_eff_sub_q[0]     = ce1_sub;
  assign mid_pipe_exp_prod_q[0]    = ce1_exp_product;
  assign mid_pipe_exp_diff_q[0]    = ce1_exp_diff;
  assign mid_pipe_tent_exp_q[0]    = ce1_tent_exp;
  assign mid_pipe_add_shamt_q[0]   = ce1_shift;
  assign mid_pipe_sticky_q[0]      = ce1_sticky;
  assign mid_pipe_sum_q[0]         = sum;
  assign mid_pipe_final_sign_q[0]  = final_sign;
  assign mid_pipe_rnd_mode_q[0]    = ce1_round;
  assign mid_pipe_res_is_spec_q[0] = ce1_special;
  assign mid_pipe_spec_res_q[0]    = ce1_special_value;
  assign mid_pipe_spec_stat_q[0]   = ce1_special_flags;
  assign mid_pipe_tag_q[0]         = ce1_tag;

  assign mid_pipe_aux_q[0]         = ce1_aux;
  assign mid_pipe_valid_q[0]       = ce1_valid;
  // Input stage: Propagate pipeline ready signal to input pipe
  assign inp_pipe_ready[NUM_INP_REGS] = align_ready;

  // Generate the register stages
  for (genvar i = 0; i < NUM_SUM_REGS; i++) begin : gen_inside_pipeline
    // Internal register enable for this stage
    logic reg_ena;
    // Determine the ready signal of the current stage - advance the pipeline:
    // 1. if the next stage is ready for our data
    // 2. if the next stage only holds a bubble (not valid) -> we can pop it
    assign mid_pipe_ready[i] = mid_pipe_ready[i+1] | ~mid_pipe_valid_q[i+1];
    // Valid: enabled by ready signal, synchronous clear with the flush signal
    `ifndef VERILATOR
    /* synopsys sync_set_reset "flush_i" */
    `endif
    always_ff @(posedge (clk_i) or negedge (rst_ni)) begin
      if (!rst_ni) begin
        mid_pipe_valid_q[i+1] <= (1'b0);
      end else begin
        mid_pipe_valid_q[i+1] <= (flush_i) ? (1'b0) : (mid_pipe_valid_q[i]);
      end
    end
    // Enable register if pipleine ready and a valid data item is present
    assign reg_ena = (mid_pipe_ready[i] & mid_pipe_valid_q[i]) | reg_ena_i[NUM_INP_REGS + i];
    // Generate the pipeline registers within the stages, use enable-registers
    `FFL(mid_pipe_eff_sub_q[i+1],     mid_pipe_eff_sub_q[i],     reg_ena, '0)
    `FFL(mid_pipe_exp_prod_q[i+1],    mid_pipe_exp_prod_q[i],    reg_ena, '0)
    `FFL(mid_pipe_exp_diff_q[i+1],    mid_pipe_exp_diff_q[i],    reg_ena, '0)
    `FFL(mid_pipe_tent_exp_q[i+1],    mid_pipe_tent_exp_q[i],    reg_ena, '0)
    `FFL(mid_pipe_add_shamt_q[i+1],   mid_pipe_add_shamt_q[i],   reg_ena, '0)
    `FFL(mid_pipe_sticky_q[i+1],      mid_pipe_sticky_q[i],      reg_ena, '0)
    `FFL(mid_pipe_sum_q[i+1],         mid_pipe_sum_q[i],         reg_ena, '0)
    `FFL(mid_pipe_final_sign_q[i+1],  mid_pipe_final_sign_q[i],  reg_ena, '0)
    `FFL(mid_pipe_rnd_mode_q[i+1],    mid_pipe_rnd_mode_q[i],    reg_ena, fpnew_pkg::RNE)
    `FFL(mid_pipe_res_is_spec_q[i+1], mid_pipe_res_is_spec_q[i], reg_ena, '0)
    `FFL(mid_pipe_spec_res_q[i+1],    mid_pipe_spec_res_q[i],    reg_ena, '0)
    `FFL(mid_pipe_spec_stat_q[i+1],   mid_pipe_spec_stat_q[i],   reg_ena, '0)
    `FFL(mid_pipe_tag_q[i+1],         mid_pipe_tag_q[i],         reg_ena, TagType'('0))

    `FFL(mid_pipe_aux_q[i+1],         mid_pipe_aux_q[i],         reg_ena, AuxType'('0))
  end
  // Output stage: assign selected pipe outputs to signals for later use
  assign effective_subtraction_q = mid_pipe_eff_sub_q[NUM_SUM_REGS];
  assign exponent_product_q      = mid_pipe_exp_prod_q[NUM_SUM_REGS];
  assign exponent_difference_q   = mid_pipe_exp_diff_q[NUM_SUM_REGS];
  assign tentative_exponent_q    = mid_pipe_tent_exp_q[NUM_SUM_REGS];
  assign addend_shamt_q          = mid_pipe_add_shamt_q[NUM_SUM_REGS];
  assign sticky_before_add_q     = mid_pipe_sticky_q[NUM_SUM_REGS];
  assign sum_q                   = mid_pipe_sum_q[NUM_SUM_REGS];
  assign final_sign_q            = mid_pipe_final_sign_q[NUM_SUM_REGS];
  assign rnd_mode_q              = mid_pipe_rnd_mode_q[NUM_SUM_REGS];
  assign result_is_special_q     = mid_pipe_res_is_spec_q[NUM_SUM_REGS];
  assign special_result_q        = mid_pipe_spec_res_q[NUM_SUM_REGS];
  assign special_status_q        = mid_pipe_spec_stat_q[NUM_SUM_REGS];

  // --------------
  // Normalization
  // --------------
  logic        [LOWER_SUM_WIDTH-1:0]  sum_lower;              // lower 2p+3 bits of sum are searched
  logic        [LZC_RESULT_WIDTH-1:0] leading_zero_count;     // the number of leading zeroes
  logic signed [LZC_RESULT_WIDTH:0]   leading_zero_count_sgn; // signed leading-zero count
  logic                               lzc_zeroes;             // in case only zeroes found

  logic        [SHIFT_AMOUNT_WIDTH-1:0] norm_shamt; // Normalization shift amount
  logic signed [EXP_WIDTH-1:0]          normalized_exponent;

  logic [3*PRECISION_BITS+4:0] sum_shifted;       // result after first normalization shift
  logic [PRECISION_BITS:0]     final_mantissa;    // final mantissa before rounding with round bit
  logic [2*PRECISION_BITS+2:0] sum_sticky_bits;   // remaining 2p+3 sticky bits after normalization
  logic                        sticky_after_norm; // sticky bit after normalization

  logic signed [EXP_WIDTH-1:0] final_exponent;

  assign sum_lower = sum_q[LOWER_SUM_WIDTH-1:0];

  // Leading zero counter for cancellations
  lzc #(
    .WIDTH ( LOWER_SUM_WIDTH ),
    .MODE  ( 1               ) // MODE = 1 counts leading zeroes
  ) i_lzc (
    .in_i    ( sum_lower          ),
    .cnt_o   ( leading_zero_count ),
    .empty_o ( lzc_zeroes         )
  );

  assign leading_zero_count_sgn = signed'({1'b0, leading_zero_count});

  // Normalization shift amount based on exponents and LZC (unsigned as only left shifts)
  always_comb begin : norm_shift_amount
    // Product-anchored case or cancellations require LZC
    if ((exponent_difference_q <= 0) || (effective_subtraction_q && (exponent_difference_q <= 2))) begin
      // Normal result (biased exponent > 0 and not a zero)
      if ((exponent_product_q - leading_zero_count_sgn + 1 >= 0) && !lzc_zeroes) begin
        // Undo initial product shift, remove the counted zeroes
        norm_shamt          = PRECISION_BITS + 2 + leading_zero_count;
        normalized_exponent = exponent_product_q - leading_zero_count_sgn + 1; // account for shift
      // Subnormal result
      end else begin
        // Cap the shift distance to align mantissa with minimum exponent
        norm_shamt          = unsigned'(signed'(PRECISION_BITS) + 2 + exponent_product_q);
        normalized_exponent = 0; // subnormals encoded as 0
      end
    // Addend-anchored case
    end else begin
      norm_shamt          = addend_shamt_q; // Undo the initial shift
      normalized_exponent = tentative_exponent_q;
    end
  end


// CE64 elastic checkpoint ce2: arithmetic expressions remain unchanged.
logic ce2_valid,ce2_ready;
logic [3*PRECISION_BITS+3:0] ce2_sum;
logic [SHIFT_AMOUNT_WIDTH-1:0] ce2_shift;
logic signed [EXP_WIDTH-1:0] ce2_exponent;
logic ce2_sticky;
logic ce2_sign;
fpnew_pkg::roundmode_e ce2_round;
logic ce2_sub;
logic ce2_special;
fp_t ce2_special_value;
fpnew_pkg::status_t ce2_special_flags;
TagType ce2_tag;

AuxType ce2_aux;
assign ce2_ready=norm_pipe_ready[0] || !ce2_valid;
always_ff @(posedge clk_i or negedge rst_ni) begin
if(!rst_ni) begin
ce2_valid<=0;
ce2_sum<='0;
ce2_shift<='0;
ce2_exponent<='0;
ce2_sticky<='0;
ce2_sign<='0;
ce2_round<=fpnew_pkg::RNE;
ce2_sub<='0;
ce2_special<='0;
ce2_special_value<='0;
ce2_special_flags<='0;
ce2_tag<=TagType'('0);

ce2_aux<=AuxType'('0);
end else if(flush_i) ce2_valid<=0;
else begin
ce2_valid<=mid_pipe_valid_q[NUM_SUM_REGS];
if(mid_pipe_valid_q[NUM_SUM_REGS]) begin
ce2_sum<=sum_q;
ce2_shift<=norm_shamt;
ce2_exponent<=normalized_exponent;
ce2_sticky<=sticky_before_add_q;
ce2_sign<=final_sign_q;
ce2_round<=rnd_mode_q;
ce2_sub<=effective_subtraction_q;
ce2_special<=result_is_special_q;
ce2_special_value<=special_result_q;
ce2_special_flags<=special_status_q;
ce2_tag<=mid_pipe_tag_q[NUM_SUM_REGS];

ce2_aux<=mid_pipe_aux_q[NUM_SUM_REGS];
end end end
  // Do the large normalization shift
  assign sum_shifted       = ce2_sum << ce2_shift;

  // The addend-anchored case needs a 1-bit normalization since the leading-one can be to the left
  // or right of the (non-carry) MSB of the sum.
  always_comb begin : small_norm
    // Default assignment, discarding carry bit
    {final_mantissa, sum_sticky_bits} = sum_shifted[3*PRECISION_BITS+3:0];
    final_exponent                    = ce2_exponent;

    // The normalized sum has overflown, align right and fix exponent
    if (sum_shifted[3*PRECISION_BITS+4]) begin // check the carry bit
      {final_mantissa, sum_sticky_bits} = sum_shifted[3*PRECISION_BITS+4:1];
      final_exponent                    = ce2_exponent + 1;
    // The normalized sum is normal, nothing to do
    end else if (sum_shifted[3*PRECISION_BITS+3]) begin // check the sum MSB
      // do nothing
    // The normalized sum is still denormal, align left - unless the result is not already subnormal
    end else if (ce2_exponent > 1) begin
      {final_mantissa, sum_sticky_bits} = {sum_shifted[3*PRECISION_BITS+2:0], 1'b0};
      final_exponent                    = ce2_exponent - 1;
    // Otherwise we're denormal
    end else begin
      final_exponent = '0;
    end
  end

  // Update the sticky bit with the shifted-out bits
  assign sticky_after_norm = (| {sum_sticky_bits}) | ce2_sticky;

  // ----------------------------
  // Rounding and classification
  // ----------------------------
  logic                         pre_round_sign;
  logic [EXP_BITS-1:0]          pre_round_exponent;
  logic [MAN_BITS-1:0]          pre_round_mantissa;
  logic [EXP_BITS+MAN_BITS-1:0] pre_round_abs; // absolute value of result before rounding
  logic [1:0]                   round_sticky_bits;

  logic of_before_round, of_after_round; // overflow
  logic uf_after_round; // underflow

  logic                         rounded_sign;
  logic [EXP_BITS+MAN_BITS-1:0] rounded_abs; // absolute value of result after rounding

  // Classification before round. RISC-V mandates checking underflow AFTER rounding!
  assign of_before_round = final_exponent >= 2**(EXP_BITS)-1; // infinity exponent is all ones

  // Assemble result before rounding. In case of overflow, the largest normal value is set.
  assign pre_round_sign     = ce2_sign;
  assign pre_round_exponent = (of_before_round) ? 2**EXP_BITS-2 : unsigned'(final_exponent[EXP_BITS-1:0]);
  assign pre_round_mantissa = (of_before_round) ? '1 : final_mantissa[MAN_BITS:1]; // bit 0 is R bit
  assign pre_round_abs      = {pre_round_exponent, pre_round_mantissa};

  // In case of overflow, the round and sticky bits are set for proper rounding
  assign round_sticky_bits  = (of_before_round) ? 2'b11 : {final_mantissa[0], sticky_after_norm};

  // ----------------------
  // Normalization Pipeline
  // ----------------------
  logic [0:NUM_NORM_REGS][EXP_BITS+MAN_BITS-1:0] norm_pipe_abs_q;
  logic [0:NUM_NORM_REGS]                        norm_pipe_sign_q;
  logic [0:NUM_NORM_REGS][1:0]                   norm_pipe_round_sticky_q;
  fpnew_pkg::roundmode_e [0:NUM_NORM_REGS]       norm_pipe_rnd_mode_q;
  logic [0:NUM_NORM_REGS]                        norm_pipe_eff_sub_q;
  logic [0:NUM_NORM_REGS]                        norm_pipe_of_before_round_q;
  logic [0:NUM_NORM_REGS]                        norm_pipe_sum_sticky_msb_q;
  logic [0:NUM_NORM_REGS]                        norm_pipe_res_is_spec_q;
  fp_t  [0:NUM_NORM_REGS]                        norm_pipe_spec_res_q;
  fpnew_pkg::status_t [0:NUM_NORM_REGS]          norm_pipe_spec_stat_q;
  TagType [0:NUM_NORM_REGS]                      norm_pipe_tag_q;

  AuxType [0:NUM_NORM_REGS]                      norm_pipe_aux_q;
  logic   [0:NUM_NORM_REGS]                      norm_pipe_valid_q;

  assign norm_pipe_abs_q[0]             = pre_round_abs;
  assign norm_pipe_sign_q[0]            = pre_round_sign;
  assign norm_pipe_round_sticky_q[0]    = round_sticky_bits;
  assign norm_pipe_rnd_mode_q[0]        = ce2_round;
  assign norm_pipe_eff_sub_q[0]         = ce2_sub;
  assign norm_pipe_of_before_round_q[0] = of_before_round;
  assign norm_pipe_sum_sticky_msb_q[0]  = sum_sticky_bits[MAN_BITS*2 + 4];
  assign norm_pipe_res_is_spec_q[0]     = ce2_special;
  assign norm_pipe_spec_res_q[0]        = ce2_special_value;
  assign norm_pipe_spec_stat_q[0]       = ce2_special_flags;
  assign norm_pipe_tag_q[0]             = ce2_tag;

  assign norm_pipe_aux_q[0]             = ce2_aux;
  assign norm_pipe_valid_q[0]           = ce2_valid;

  assign mid_pipe_ready[NUM_SUM_REGS] = ce2_ready;

  for (genvar i = 0; i < NUM_NORM_REGS; i++) begin : gen_norm_pipeline
    logic reg_ena;
    assign norm_pipe_ready[i] = norm_pipe_ready[i+1] | ~norm_pipe_valid_q[i+1];
    `ifndef VERILATOR
    /* synopsys sync_set_reset "flush_i" */
    `endif
    always_ff @(posedge (clk_i) or negedge (rst_ni)) begin
      if (!rst_ni) begin
        norm_pipe_valid_q[i+1] <= (1'b0);
      end else begin
        norm_pipe_valid_q[i+1] <= (flush_i) ? (1'b0) : (norm_pipe_valid_q[i]);
      end
    end
    assign reg_ena = (norm_pipe_ready[i] & norm_pipe_valid_q[i]) | reg_ena_i[NUM_INP_REGS + NUM_SUM_REGS + i];
    `FFL(norm_pipe_abs_q[i+1],             norm_pipe_abs_q[i],             reg_ena, '0)
    `FFL(norm_pipe_sign_q[i+1],            norm_pipe_sign_q[i],            reg_ena, '0)
    `FFL(norm_pipe_round_sticky_q[i+1],    norm_pipe_round_sticky_q[i],    reg_ena, '0)
    `FFL(norm_pipe_rnd_mode_q[i+1],        norm_pipe_rnd_mode_q[i],        reg_ena, fpnew_pkg::RNE)
    `FFL(norm_pipe_eff_sub_q[i+1],         norm_pipe_eff_sub_q[i],         reg_ena, '0)
    `FFL(norm_pipe_of_before_round_q[i+1], norm_pipe_of_before_round_q[i], reg_ena, '0)
    `FFL(norm_pipe_sum_sticky_msb_q[i+1],  norm_pipe_sum_sticky_msb_q[i],  reg_ena, '0)
    `FFL(norm_pipe_res_is_spec_q[i+1],     norm_pipe_res_is_spec_q[i],     reg_ena, '0)
    `FFL(norm_pipe_spec_res_q[i+1],        norm_pipe_spec_res_q[i],        reg_ena, '0)
    `FFL(norm_pipe_spec_stat_q[i+1],       norm_pipe_spec_stat_q[i],       reg_ena, '0)
    `FFL(norm_pipe_tag_q[i+1],             norm_pipe_tag_q[i],             reg_ena, TagType'('0))

    `FFL(norm_pipe_aux_q[i+1],             norm_pipe_aux_q[i],             reg_ena, AuxType'('0))
  end

  // Perform the rounding
  // Local inline derivative of frozen fpnew_rounding; see fork-provenance.json.
  if(1)begin : i_fpnew_rounding
    localparam int unsigned AbsWidth=EXP_BITS+MAN_BITS;
    wire [AbsWidth-1:0] abs_value_i=norm_pipe_abs_q[NUM_NORM_REGS];
    wire sign_i=norm_pipe_sign_q[NUM_NORM_REGS];
    wire [1:0] round_sticky_bits_i=norm_pipe_round_sticky_q[NUM_NORM_REGS];
    fpnew_pkg::roundmode_e rnd_mode_i;
    assign rnd_mode_i=norm_pipe_rnd_mode_q[NUM_NORM_REGS];
    wire effective_subtraction_i=norm_pipe_eff_sub_q[NUM_NORM_REGS];
    wire [AbsWidth-1:0] abs_rounded_o;
    wire sign_o;
    logic exact_zero_o;
  logic round_up; // Rounding decision

  // Take the rounding decision according to RISC-V spec
  // RoundMode | Mnemonic | Meaning
  // :--------:|:--------:|:-------
  //    000    |   RNE    | Round to Nearest, ties to Even
  //    001    |   RTZ    | Round towards Zero
  //    010    |   RDN    | Round Down (towards -\infty)
  //    011    |   RUP    | Round Up (towards \infty)
  //    100    |   RMM    | Round to Nearest, ties to Max Magnitude
  //    101    |   ROD    | Round towards odd (this mode is not define in RISC-V FP-SPEC)
  //  others   |          | *invalid*
  always_comb begin : rounding_decision
    unique case (rnd_mode_i)
      fpnew_pkg::RNE: // Decide accoring to round/sticky bits
        unique case (round_sticky_bits_i)
          2'b00,
          2'b01: round_up = 1'b0;           // < ulp/2 away, round down
          2'b10: round_up = abs_value_i[0]; // = ulp/2 away, round towards even result
          2'b11: round_up = 1'b1;           // > ulp/2 away, round up
          default: round_up = fpnew_pkg::DONT_CARE;
        endcase
      fpnew_pkg::RTZ: round_up = 1'b0; // always round down
      fpnew_pkg::RDN: round_up = (| round_sticky_bits_i) ? sign_i  : 1'b0; // to 0 if +, away if -
      fpnew_pkg::RUP: round_up = (| round_sticky_bits_i) ? ~sign_i : 1'b0; // to 0 if -, away if +
      fpnew_pkg::RMM: round_up = round_sticky_bits_i[1]; // round down if < ulp/2 away, else up
      fpnew_pkg::ROD: round_up = ~abs_value_i[0] & (| round_sticky_bits_i);
      default: round_up = fpnew_pkg::DONT_CARE; // propagate x
    endcase
  end

  // Perform the rounding, exponent change and overflow to inf happens automagically
  assign abs_rounded_o = abs_value_i + round_up;

  // True zero result is a zero result without dirty round/sticky bits
  assign exact_zero_o = (abs_value_i == '0) && (round_sticky_bits_i == '0);

  // In case of effective subtraction (thus signs of addition operands must have differed) and a
  // true zero result, the result sign is '-' in case of RDN and '+' for other modes.
  assign sign_o = (exact_zero_o && effective_subtraction_i)
                  ? (rnd_mode_i == fpnew_pkg::RDN)
                  : sign_i;
    assign rounded_abs=abs_rounded_o;
    assign rounded_sign=sign_o;
  end

  // Classification after rounding
  assign uf_after_round = (rounded_abs[EXP_BITS+MAN_BITS-1:MAN_BITS] == '0) // denormal
        || ((norm_pipe_abs_q[NUM_NORM_REGS][EXP_BITS+MAN_BITS-1:MAN_BITS] == '0) && (rounded_abs[EXP_BITS+MAN_BITS-1:MAN_BITS] == 1) &&
           ((norm_pipe_round_sticky_q[NUM_NORM_REGS] != 2'b11) || (!norm_pipe_sum_sticky_msb_q[NUM_NORM_REGS] && ((norm_pipe_rnd_mode_q[NUM_NORM_REGS] == fpnew_pkg::RNE) || (norm_pipe_rnd_mode_q[NUM_NORM_REGS] == fpnew_pkg::RMM)))));
  assign of_after_round = rounded_abs[EXP_BITS+MAN_BITS-1:MAN_BITS] == '1; // exponent all ones

  // -----------------
  // Result selection
  // -----------------
  logic [WIDTH-1:0]     regular_result;
  fpnew_pkg::status_t   regular_status;

  // Assemble regular result
  assign regular_result    = {rounded_sign, rounded_abs};
  assign regular_status.NV = 1'b0; // only valid cases are handled in regular path
  assign regular_status.DZ = 1'b0; // no divisions
  assign regular_status.OF = norm_pipe_of_before_round_q[NUM_NORM_REGS] | of_after_round;   // rounding can introduce overflow
  assign regular_status.UF = uf_after_round & regular_status.NX; // only inexact results raise UF
  assign regular_status.NX = (| norm_pipe_round_sticky_q[NUM_NORM_REGS]) | norm_pipe_of_before_round_q[NUM_NORM_REGS] | of_after_round;

  // Final results for output pipeline
  fp_t                result_d;
  fpnew_pkg::status_t status_d;

  // Select output depending on special case detection
  assign result_d = norm_pipe_res_is_spec_q[NUM_NORM_REGS] ? norm_pipe_spec_res_q[NUM_NORM_REGS] : regular_result;
  assign status_d = norm_pipe_res_is_spec_q[NUM_NORM_REGS] ? norm_pipe_spec_stat_q[NUM_NORM_REGS] : regular_status;

  // Predict only the final exponent classification in parallel with the
  // numeric rounding adder. The full result/flags and their FFs are unchanged.
  localparam int NF_ABS_WIDTH=EXP_BITS+MAN_BITS;
  wire [NF_ABS_WIDTH-1:0] nf_abs=norm_pipe_abs_q[NUM_NORM_REGS];
  wire nf_up=i_fpnew_rounding.round_up;
  wire nf_operands_known=((nf_abs^nf_abs)==={NF_ABS_WIDTH{1'b0}})&&
    ((nf_up^nf_up)===1'b0);
  wire nf_mantissa_carry=nf_up & (&nf_abs[MAN_BITS-1:0]);
  wire nf_regular_fast=(&nf_abs[NF_ABS_WIDTH-1:MAN_BITS+1]) &
    (nf_abs[MAN_BITS]^nf_mantissa_carry);
  wire nf_regular=nf_operands_known ? nf_regular_fast :
    (rounded_abs[NF_ABS_WIDTH-1:MAN_BITS]=='1);
  wire nf_input=(norm_pipe_res_is_spec_q[NUM_NORM_REGS]===1'b1) ?
    (norm_pipe_spec_res_q[NUM_NORM_REGS][WIDTH-2:MAN_BITS]=='1) :
    ((norm_pipe_res_is_spec_q[NUM_NORM_REGS]===1'b0) ? nf_regular :
      (result_d[WIDTH-2:MAN_BITS]=='1));

  // ----------------
  // Output Pipeline
  // ----------------
  // Output pipeline signals, index i holds signal after i register stages
  fp_t                [0:NUM_OUT_REGS] out_pipe_result_q;
  fpnew_pkg::status_t [0:NUM_OUT_REGS] out_pipe_status_q;
  TagType             [0:NUM_OUT_REGS] out_pipe_tag_q;

  AuxType             [0:NUM_OUT_REGS] out_pipe_aux_q;
  logic               [0:NUM_OUT_REGS] out_pipe_valid_q;
  // Ready signal is combinatorial for all stages
  logic [0:NUM_OUT_REGS] out_pipe_ready;
  logic [0:NUM_OUT_REGS] out_pipe_nonfinite_q,out_pipe_nf_exact_q;
  assign out_pipe_nonfinite_q[0]=nf_input;
  assign out_pipe_nf_exact_q[0]=1'b1;

  // Input stage: First element of pipeline is taken from inputs
  assign out_pipe_result_q[0] = result_d;
  assign out_pipe_status_q[0] = status_d;
  assign out_pipe_tag_q[0]    = norm_pipe_tag_q[NUM_NORM_REGS];

  assign out_pipe_aux_q[0]    = norm_pipe_aux_q[NUM_NORM_REGS];
  assign out_pipe_valid_q[0]  = norm_pipe_valid_q[NUM_NORM_REGS];
  // Input stage: Propagate pipeline ready signal to normalization pipe
  assign norm_pipe_ready[NUM_NORM_REGS] = out_pipe_ready[0];
  // Generate the register stages
  for (genvar i = 0; i < NUM_OUT_REGS; i++) begin : gen_output_pipeline
    // Internal register enable for this stage
    logic reg_ena;
    // Determine the ready signal of the current stage - advance the pipeline:
    // 1. if the next stage is ready for our data
    // 2. if the next stage only holds a bubble (not valid) -> we can pop it
    assign out_pipe_ready[i] = out_pipe_ready[i+1] | ~out_pipe_valid_q[i+1];
    // Valid: enabled by ready signal, synchronous clear with the flush signal
    `ifndef VERILATOR
    /* synopsys sync_set_reset "flush_i" */
    `endif
    always_ff @(posedge (clk_i) or negedge (rst_ni)) begin
      if (!rst_ni) begin
        out_pipe_valid_q[i+1] <= (1'b0);
      end else begin
        out_pipe_valid_q[i+1] <= (flush_i) ? (1'b0) : (out_pipe_valid_q[i]);
      end
    end
    // Enable register if pipleine ready and a valid data item is present
    assign reg_ena = (out_pipe_ready[i] & out_pipe_valid_q[i]) | reg_ena_i[NUM_INP_REGS + NUM_MID_REGS + i];
    // Generate the pipeline registers within the stages, use enable-registers
    `FFL(out_pipe_result_q[i+1], out_pipe_result_q[i], reg_ena, '0)
    `FFL(out_pipe_nonfinite_q[i+1],out_pipe_nonfinite_q[i],reg_ena,1'b0)
    // FFL uses a ternary load and bit-merges on X/Z. Classification does
    // not commute with such a merge: use the unchanged result comparison
    // until a complete known-enable transaction overwrites that stage.
    always_ff @(posedge clk_i or negedge rst_ni)begin
      if(!rst_ni)out_pipe_nf_exact_q[i+1]<=1'b1;
      else out_pipe_nf_exact_q[i+1]<=((reg_ena^reg_ena)===1'b0) &
        (reg_ena ? out_pipe_nf_exact_q[i] : out_pipe_nf_exact_q[i+1]);
    end
    `FFL(out_pipe_status_q[i+1], out_pipe_status_q[i], reg_ena, '0)
    `FFL(out_pipe_tag_q[i+1],    out_pipe_tag_q[i],    reg_ena, TagType'('0))

    `FFL(out_pipe_aux_q[i+1],    out_pipe_aux_q[i],    reg_ena, AuxType'('0))
  end
  // Output stage: Ready travels backwards from output side, driven by downstream circuitry
  assign out_pipe_ready[NUM_OUT_REGS] = out_ready_i;
  // Output stage: assign module outputs
  assign result_o        = out_pipe_result_q[NUM_OUT_REGS];
  assign status_o        = out_pipe_status_q[NUM_OUT_REGS];
  if(NUM_OUT_REGS==0)begin:nf_unregistered
    assign nonfinite_o=(result_o[WIDTH-2:MAN_BITS]=='1);
  end else begin:nf_registered
    assign nonfinite_o=out_pipe_nf_exact_q[NUM_OUT_REGS] ?
      out_pipe_nonfinite_q[NUM_OUT_REGS] : (result_o[WIDTH-2:MAN_BITS]=='1);
  end

  assign tag_o           = out_pipe_tag_q[NUM_OUT_REGS];

  assign aux_o           = out_pipe_aux_q[NUM_OUT_REGS];
  assign out_valid_o     = out_pipe_valid_q[NUM_OUT_REGS];


















endmodule
